with cleaned as (select id, name, country, city, signup_date, is_active, credit_limit, round(age, 0) as age_rounded, concat(email, ' - ', segment) as email_segment, coalesce(segment, 'N/A') as segment_clean from customers where signup_date >= date '2024-03-06' and segment is not null) select s.*, top1.session_device from cleaned s left join lateral (select c.device as session_device from sessions c where c.customer_id = s.id order by c.started_at desc, c.id desc limit 1) top1 on true
